-- 本人已处置本地/渲染任务释放媒体外键；用canvas_migration.py --apply精确核验旧结构。
ALTER TABLE canvas_local_jobs ADD COLUMN disposal_receipt_id BIGINT UNSIGNED, DROP FOREIGN KEY fk_canvas_local_jobs_source_media_id, MODIFY COLUMN source_media_id BIGINT UNSIGNED, DROP CHECK ck_canvas_local_output, ADD CONSTRAINT ck_canvas_local_disposal CHECK (disposal_receipt_id IS NULL OR (project_id IS NOT NULL AND canvas_id IS NOT NULL AND status IN ('succeeded','failed','cancelled') AND lease_token IS NULL AND locked_until IS NULL AND JSON_LENGTH(request_json) = 0 AND JSON_LENGTH(source_snapshot) = 0 AND 0 <> COALESCE(JSON_UNQUOTE(JSON_EXTRACT(error_json, '$.code')) = 'canvas_work_disposed', FALSE))), ADD CONSTRAINT ck_canvas_local_output CHECK (status <> 'succeeded' OR (result_json IS NOT NULL AND finished_at IS NOT NULL AND (task_type <> 'depth_capture' OR output_media_id IS NOT NULL OR disposal_receipt_id IS NOT NULL))), ADD CONSTRAINT ck_canvas_local_source CHECK (source_media_id IS NOT NULL OR disposal_receipt_id IS NOT NULL), ADD CONSTRAINT fk_canvas_local_disposal FOREIGN KEY(disposal_receipt_id) REFERENCES canvas_write_receipts (id) ON DELETE RESTRICT ON UPDATE RESTRICT, ADD CONSTRAINT fk_canvas_local_source FOREIGN KEY(source_media_id) REFERENCES media_files (id) ON DELETE RESTRICT ON UPDATE RESTRICT, ADD INDEX idx_canvas_local_disposal (disposal_receipt_id);

ALTER TABLE canvas_render_jobs ADD COLUMN disposal_receipt_id BIGINT UNSIGNED, DROP CHECK ck_canvas_render_output, ADD CONSTRAINT ck_canvas_render_disposal CHECK (disposal_receipt_id IS NULL OR (status IN ('succeeded','failed','cancelled') AND lease_token IS NULL AND locked_until IS NULL AND JSON_LENGTH(request_json) = 0 AND JSON_LENGTH(source_snapshot) = 0 AND JSON_LENGTH(plan_json) = 0 AND 0 <> COALESCE(JSON_UNQUOTE(JSON_EXTRACT(error_json, '$.code')) = 'canvas_work_disposed', FALSE))), ADD CONSTRAINT ck_canvas_render_output CHECK (status <> 'succeeded' OR ((output_media_id IS NOT NULL OR disposal_receipt_id IS NOT NULL) AND result_json IS NOT NULL AND finished_at IS NOT NULL)), ADD CONSTRAINT fk_canvas_render_disposal FOREIGN KEY(disposal_receipt_id) REFERENCES canvas_write_receipts (id) ON DELETE RESTRICT ON UPDATE RESTRICT, ADD INDEX idx_canvas_render_disposal (disposal_receipt_id);
